    RETURN;
  END IF;

  -- 01. Sulfonilureas y pioglitazona: eficacia, hipoglucemia, peso y desintensificación
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La pastilla barata que causó una caída","texto":"Doña Elvira tiene 76 años, vive en un municipio de Boyacá y toma glibenclamida 5 mg al día. Un domingo no desayunó, se sintió mareada y cayó en el baño. La glucosa era de 48 mg/dL. La sulfonilurea era eficaz y económica, pero no era segura para ella en ese contexto. Elegir un fármaco barato no es lo mismo que elegir el fármaco correcto."},"objetivos":["Explicar el mecanismo y el perfil de eficacia de las sulfonilureas y la pioglitazona.","Identificar los factores que aumentan el riesgo de hipoglucemia con sulfonilureas.","Reconocer cuándo la pioglitazona está contraindicada o requiere precaución.","Aplicar criterios de desintensificación en adultos mayores y pacientes frágiles."],"conceptos":[{"icono":"Zap","termino":"Sulfonilurea","definicion":"Fármaco que estimula la secreción de insulina por la célula beta. Es eficaz, económico y puede causar hipoglucemia y aumento de peso."},{"icono":"Scale","termino":"Pioglitazona","definicion":"Agonista de PPARγ que mejora la sensibilidad a la insulina. Útil en hígado graso, pero causa retención de líquidos y aumento de peso."},{"icono":"AlertTriangle","termino":"Hipoglucemia","definicion":"Glucosa <70 mg/dL. Con sulfonilureas puede ser prolongada y grave, sobre todo en insuficiencia renal o mala ingesta."},{"icono":"RefreshCw","termino":"Desintensificación","definicion":"Reducción o retiro de fármacos cuando el riesgo supera el beneficio, por edad, fragilidad, hipoglucemias o cambio de metas."}],"secciones":[{"titulo":"Sulfonilureas: eficacia con un precio","parrafos":["Las sulfonilureas estimulan la célula beta para secretar insulina, independientemente de la glucosa. Por eso son eficaces, rápidas y económicas, pero también pueden causar hipoglucemia, especialmente si el paciente no come, tiene insuficiencia renal o toma dosis altas. La glibenclamida tiene un riesgo particularmente alto de hipoglucemia prolongada en adultos mayores.","Su lugar en 2026 es limitado pero real: pacientes con bajo riesgo de hipoglucemia, acceso limitado a otras opciones y necesidad de un fármaco potente y barato. No son la mejor elección en personas mayores, frágiles, con TFG baja, con comidas irregulares o con antecedente de hipoglucemia grave."]},{"titulo":"Pioglitazona: sensibilidad y retención de líquidos","parrafos":["La pioglitazona mejora la sensibilidad a la insulina en músculo, hígado y tejido adiposo. Puede ser útil en pacientes con hígado graso y resistencia a la insulina, y tiene un efecto favorable sobre los lípidos. Sin embargo, causa retención de líquidos, aumento de peso y edema, y no se recomienda en insuficiencia cardíaca.","También se asocia con un mayor riesgo de fracturas y, en algunos estudios, con cáncer de vejiga, aunque la evidencia es controvertida. No es un fármaco de primera línea en la mayoría de los pacientes y requiere revisar la función hepática y el riesgo cardiovascular."]},{"titulo":"Desintensificar también es tratar","parrafos":["Cuando una persona mayor logra la meta con un esquema que causa hipoglucemias, el tratamiento debe simplificarse. La desintensificación puede consistir en reducir la sulfonilurea, retirar un fármaco que no aporta o cambiar a una opción con menor riesgo. La meta no es solo la HbA1c, sino evitar caídas, confusión y hospitalizaciones.","La decisión se acuerda con el paciente y la familia. Se explican los riesgos de la hipoglucemia, se revisan las comidas y se ajusta el esquema. El Químico Farmacéutico puede detectar la señal en la farmacia y comunicarla al equipo tratante con datos concretos."]}],"errores":[{"error":"Elegir sulfonilurea solo por costo.","correccion":"El costo importa, pero la seguridad y el riesgo de hipoglucemia también. En pacientes de riesgo, una opción más segura puede evitar hospitalizaciones."},{"error":"Usar pioglitazona en insuficiencia cardíaca.","correccion":"La retención de líquidos puede descompensar la insuficiencia cardíaca; está contraindicada en ese contexto."},{"error":"No preguntar por hipoglucemias en el control.","correccion":"Las hipoglucemias pueden ser asintomáticas o atribuidas a otras causas; hay que buscarlas."}],"comprueba":[{"pregunta":"¿Cuál es el principal riesgo de las sulfonilureas?","respuesta":"La hipoglucemia, que puede ser prolongada y grave."},{"pregunta":"¿Cuándo se evita la pioglitazona?","respuesta":"En insuficiencia cardíaca, retención de líquidos y osteoporosis avanzada."},{"pregunta":"¿Qué es desintensificar?","respuesta":"Reducir o retirar fármacos cuando el riesgo supera el beneficio, con una meta más segura."}],"resumen":["Las sulfonilureas son **eficaces y económicas**, pero causan hipoglucemia.","La pioglitazona mejora la sensibilidad, pero **retiene líquidos**.","En fragilidad, la **desintensificación** es una intervención de calidad.","La decisión se basa en el paciente, no solo en la HbA1c."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Ilustración de una persona mayor en el baño con un glucómetro marcando 48 mg/dL y una caja de glibenclamida sobre el lavabo.","alt":"Hipoglucemia por sulfonilurea en una persona mayor"}],"keywords":["sulfonilureas hipoglucemia","glibenclamida adultos mayores","pioglitazona contraindicaciones","desintensificación diabetes","sulfonilurea insuficiencia renal","pioglitazona insuficiencia cardiaca","diabetes adulto mayor","curso farmacoterapia diabetes"],"mapa":{"centro":"Sulfonilureas y pioglitazona","ramas":[{"titulo":"Sulfonilureas","icono":"Zap","nodos":["Secretagogos","Hipoglucemia","Aumento de peso","Bajo costo"]},{"titulo":"Pioglitazona","icono":"Scale","nodos":["Sensibilidad","Retención de líquidos","Hígado graso","Insuficiencia cardíaca"]},{"titulo":"Riesgo","icono":"AlertTriangle","nodos":["Edad avanzada","TFG baja","Comidas irregulares","Fragilidad"]},{"titulo":"Decisión","icono":"RefreshCw","nodos":["Individualizar","Desintensificar","Educar","Seguir"]}]},"proceso":{"titulo":"Cómo revisar una sulfonilurea o pioglitazona","intro":"","pasos":[{"titulo":"Revisar la meta","detalle":"Edad, fragilidad, comorbilidad y riesgo de hipoglucemia.","icono":"Target","evidencia":"Meta documentada."},{"titulo":"Revisar la TFG","detalle":"Ajustar o evitar según la función renal y el fármaco.","icono":"Droplets","evidencia":"TFG registrada."},{"titulo":"Buscar hipoglucemias","detalle":"Preguntar por sudoración, temblor, confusión o caídas.","icono":"AlertTriangle","evidencia":"Eventos registrados."},{"titulo":"Revisar comidas","detalle":"Horarios, ayunos y tolerancia alimentaria.","icono":"CalendarClock","evidencia":"Entrevista."},{"titulo":"Proponer ajuste","detalle":"Reducir, cambiar o desintensificar con el equipo.","icono":"RefreshCw","evidencia":"Intervención."}]},"caso":{"titulo":"La caída de doña Elvira","contexto":"Mujer de 76 años, TFG 42 ml/min, HbA1c 7,2 %, glibenclamida 5 mg al día y metformina 850 mg cada 12 horas. Tuvo una hipoglucemia de 48 mg/dL tras un ayuno prolongado.","pregunta":"¿Cuál es la intervención más segura?","opciones":[{"texto":"Mantener la glibenclamida y recomendarle que no ayune.","correcta":false,"retro":"La hipoglucemia ya ocurrió y el riesgo persiste. No basta con una recomendación aislada."},{"texto":"Proponer al médico reducir o retirar la glibenclamida y revisar el esquema, con educación sobre hipoglucemia.","correcta":true,"retro":"En una persona mayor con TFG baja e hipoglucemia, la sulfonilurea debe revisarse. La desintensificación es una intervención de seguridad."},{"texto":"Aumentar la metformina para compensar.","correcta":false,"retro":"Aumentar metformina no corrige el riesgo de hipoglucemia de la sulfonilurea y puede empeorar la tolerancia."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Sulfonilureas y pioglitazona: eficacia, hipoglucemia, peso y desintensificación$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Sulfonilureas y pioglitazona: eficacia, hipoglucemia, peso y desintensificación$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Caso: adulto mayor con ERC en tratamiento con metformina y glibenclamida
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Dos fármacos, tres problemas","texto":"Don Hernando tiene 79 años, TFG de 28 ml/min, HbA1c de 7,1 %, metformina 1 g cada 12 horas y glibenclamida 5 mg al día. Ha tenido dos hipoglucemias y una infección urinaria reciente. La metformina está contraindicada por la TFG, la glibenclamida es peligrosa por la hipoglucemia y el paciente no tiene una meta clara. El caso reúne los errores más frecuentes en diabetes avanzada."},"objetivos":["Integrar función renal, riesgo de hipoglucemia y metas en un adulto mayor.","Aplicar criterios de suspensión y ajuste de metformina y sulfonilureas.","Proponer una alternativa segura y coordinada con el equipo tratante.","Diseñar un plan de educación y seguimiento para el paciente y su cuidador."],"conceptos":[{"icono":"Droplets","termino":"ERC","definicion":"Enfermedad renal crónica; la TFG <30 ml/min contraindica metformina y obliga a revisar muchos antidiabéticos."},{"icono":"AlertTriangle","termino":"Hipoglucemia recurrente","definicion":"Dos o más episodios exigen revisar el esquema, la alimentación y la educación."},{"icono":"Users","termino":"Cuidador","definicion":"Persona que apoya la administración y la alimentación; su comprensión es parte de la seguridad."},{"icono":"Target","termino":"Meta realista","definicion":"Objetivo glucémico adaptado a la fragilidad y a la esperanza de vida, priorizando evitar hipoglucemias."}],"secciones":[{"titulo":"Qué está mal en el esquema","parrafos":["La metformina está contraindicada con TFG <30 ml/min por el riesgo de acidosis láctica. La glibenclamida, en un paciente de 79 años con enfermedad renal, es una causa frecuente de hipoglucemia prolongada. Mantener ambos fármacos sin ajuste es un problema de seguridad, aunque la HbA1c parezca aceptable.","La meta de 7,1 % no justifica el riesgo. En un adulto mayor con ERC y hipoglucemias, una meta menos estricta y un esquema más seguro son prioritarios. El caso no se resuelve subiendo o bajando una dosis: requiere revisar el plan completo."]},{"titulo":"Cómo construir una alternativa","parrafos":["Se suspende la metformina y se revisa la glibenclamida. Según la TFG, la comorbilidad y la cobertura, se puede considerar un iSGLT2 si hay indicación renal o cardíaca y la TFG lo permite, un iDPP-4 como linagliptina si se busca una opción oral sencilla, o insulina si hay hiperglucemia sintomática o catabolismo. La elección debe ser individualizada.","La educación incluye reconocer y tratar la hipoglucemia, revisar la alimentación, ajustar la técnica de medición y coordinar con el cuidador. También se revisan las interacciones y la función renal. El objetivo es un plan que el paciente pueda seguir sin caídas ni hospitalizaciones."]},{"titulo":"El papel del Químico Farmacéutico","parrafos":["El QF puede documentar la TFG, los episodios de hipoglucemia, los medicamentos y las barreras. Con esa información, propone al médico un cambio concreto y verifica que la nueva fórmula sea segura. También puede contactar al cuidador y programar un seguimiento telefónico.","La intervención no termina en la nota. Se revisa la adherencia, la tolerancia y los nuevos eventos. Si el paciente no puede acceder al fármaco propuesto, se busca una alternativa cubierta o se ajusta el plan. La sostenibilidad es parte de la seguridad."]}],"errores":[{"error":"Mantener metformina con TFG <30.","correccion":"Está contraindicada; se suspende y se busca alternativa."},{"error":"Ignorar las hipoglucemias porque la HbA1c es buena.","correccion":"Las hipoglucemias son un evento de seguridad y obligan a revisar el esquema."},{"error":"No involucrar al cuidador.","correccion":"El cuidador administra y observa síntomas; su educación es clave."}],"comprueba":[{"pregunta":"¿Qué hacer con la metformina si la TFG es 28?","respuesta":"Suspenderla; está contraindicada por riesgo de acidosis láctica."},{"pregunta":"¿Por qué la glibenclamida es peligrosa en este paciente?","respuesta":"Porque causa hipoglucemia, sobre todo en adultos mayores con ERC."},{"pregunta":"¿Qué meta priorizar?","respuesta":"Evitar hipoglucemias y mantener la calidad de vida, con una meta menos estricta."}],"resumen":["La **TFG** contraindica metformina por debajo de 30 ml/min.","Las sulfonilureas son una causa frecuente de hipoglucemia en ERC.","La **desintensificación** y la educación son parte del tratamiento.","El cambio debe ser coordinado y con seguimiento."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"}],"imagenes":[{"ubicacion":"Sección del caso","descripcion":"Expediente con TFG 28, dos hipoglucemias y una caja de metformina tachada con una X.","alt":"Caso de adulto mayor con ERC y hipoglucemias"}],"keywords":["metformina tfg 28","glibenclamida hipoglucemia","diabetes adulto mayor erc","desintensificación diabetes","caso clínico diabetes","metformina contraindicada","sulfonilurea insuficiencia renal"],"mapa":{"centro":"Adulto mayor con ERC","ramas":[{"titulo":"Metformina","icono":"Pill","nodos":["TFG <30","Suspender","Riesgo de acidosis"]},{"titulo":"Glibenclamida","icono":"Zap","nodos":["Hipoglucemia","TFG baja","Retirar o reducir"]},{"titulo":"Meta","icono":"Target","nodos":["Menos estricta","Evitar caídas","Calidad de vida"]},{"titulo":"Alternativa","icono":"ShieldCheck","nodos":["iSGLT2 si aplica","iDPP-4","Insulina si es necesaria"]}]},"proceso":{"titulo":"Abordaje del adulto mayor con ERC","intro":"","pasos":[{"titulo":"Calcular TFG","detalle":"Confirmar la función renal y clasificar la ERC.","icono":"Calculator","evidencia":"TFG documentada."},{"titulo":"Revisar fármacos","detalle":"Metformina, sulfonilureas, dosis y contraindicaciones.","icono":"ClipboardList","evidencia":"Lista de medicamentos."},{"titulo":"Evaluar hipoglucemias","detalle":"Número, gravedad, horario y relación con comidas.","icono":"AlertTriangle","evidencia":"Registro de eventos."},{"titulo":"Proponer cambio","detalle":"Suspender, ajustar o cambiar con el equipo.","icono":"RefreshCw","evidencia":"Intervención."},{"titulo":"Seguir","detalle":"Revisar tolerancia, glucosa y eventos en 2 a 4 semanas.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"El esquema que hay que cambiar","contexto":"Hernando, 79 años, TFG 28 ml/min, HbA1c 7,1 %, metformina 1 g cada 12 horas, glibenclamida 5 mg al día, dos hipoglucemias en el último mes.","pregunta":"¿Cuál es la conducta más adecuada?","opciones":[{"texto":"Mantener todo porque la HbA1c está cerca de la meta.","correcta":false,"retro":"La HbA1c no refleja el riesgo de hipoglucemia ni la contraindicación renal de la metformina."},{"texto":"Suspender metformina por TFG <30, revisar la glibenclamida y proponer un esquema individualizado con el médico.","correcta":true,"retro":"La metformina está contraindicada y la sulfonilurea causa hipoglucemias. Se requiere un cambio coordinado y educación."},{"texto":"Aumentar la glibenclamida para compensar la suspensión de metformina.","correcta":false,"retro":"Aumentar la sulfonilurea empeora el riesgo de hipoglucemia."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Caso: adulto mayor con ERC en tratamiento con metformina y glibenclamida$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Caso: adulto mayor con ERC en tratamiento con metformina y glibenclamida$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
