  END IF;

  -- 03. Introducción a la unidad: iSGLT2, agonistas GLP-1 y tirzepatida, más allá de la glucosa
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El fármaco que no solo baja el azúcar","texto":"Un paciente con diabetes, insuficiencia cardíaca y albuminuria pregunta por qué le cambian la metformina por un “medicamento nuevo”. La respuesta no es que la metformina sea mala, sino que el nuevo fármaco reduce hospitalizaciones por insuficiencia cardíaca y protege el riñón. En 2026, algunos antidiabéticos se eligen por sus beneficios en órganos, no solo por la glucosa."},"objetivos":["Diferenciar los iSGLT2, los agonistas GLP-1 y tirzepatida por mecanismo y efecto.","Reconocer los beneficios cardiorrenales y de peso que van más allá de la HbA1c.","Identificar los efectos adversos y las precauciones de cada grupo.","Seleccionar el grupo adecuado según el perfil del paciente."],"conceptos":[{"icono":"Droplets","termino":"iSGLT2","definicion":"Inhibidores del cotransportador sodio-glucosa tipo 2 que aumentan la glucosuria y reducen eventos cardiorrenales."},{"icono":"Activity","termino":"Agonista GLP-1","definicion":"Fármaco que imita la incretina GLP-1, estimula la insulina dependiente de glucosa, frena el glucagón y reduce el apetito."},{"icono":"Scale","termino":"Tirzepatida","definicion":"Agonista dual GIP/GLP-1 con mayor efecto sobre el peso y la HbA1c en muchos pacientes."},{"icono":"ShieldCheck","termino":"Beneficio cardiorrenal","definicion":"Reducción de eventos cardiovasculares, hospitalizaciones por insuficiencia cardíaca o progresión renal, demostrada en ensayos."}],"secciones":[{"titulo":"Tres grupos, tres lógicas","parrafos":["Los iSGLT2 bloquean la reabsorción renal de glucosa y sodio. Su beneficio principal, además de reducir la glucosa, es disminuir las hospitalizaciones por insuficiencia cardíaca y la progresión de la enfermedad renal. No dependen de la insulina y tienen bajo riesgo de hipoglucemia, pero pueden causar infecciones genitales, depleción de volumen y cetoacidosis euglucémica.","Los agonistas GLP-1 aumentan la incretina, estimulan la insulina cuando hay glucosa, frenan el glucagón, enlentecen el vaciamiento gástrico y reducen el apetito. Algunos tienen beneficio cardiovascular y renal. La tirzepatida añade el efecto GIP y logra mayores reducciones de peso y HbA1c en muchos pacientes."]},{"titulo":"Qué paciente se beneficia","parrafos":["Un paciente con insuficiencia cardíaca o enfermedad renal se beneficia de un iSGLT2. Un paciente con enfermedad cardiovascular aterosclerótica, obesidad o alto riesgo cardiovascular puede beneficiarse de un agonista GLP-1. Un paciente con obesidad y diabetes que necesita perder peso puede considerar tirzepatida o semaglutida, según disponibilidad y cobertura.","La elección no es excluyente: un paciente con insuficiencia cardíaca, enfermedad renal y obesidad puede recibir un iSGLT2 y un agonista GLP-1. La combinación depende del riesgo, la tolerancia, el costo y la preferencia. La meta es reducir eventos y mejorar la calidad de vida, no solo bajar la HbA1c."]},{"titulo":"Lo que hay que vigilar","parrafos":["Los iSGLT2 requieren educación sobre hidratación, infecciones genitales, cetoacidosis y reglas de días de enfermedad. Los agonistas GLP-1 y tirzepatida se inician con dosis baja y titulación gradual para reducir náuseas y vómito; se vigilan pancreatitis, colelitiasis y síntomas tiroideos. La pérdida de peso debe ser gradual y acompañada de alimentación y actividad.","El Químico Farmacéutico puede revisar la técnica de inyección, la conservación, la cobertura y la adherencia. También puede detectar interacciones y educar sobre signos de alarma. La conversación sobre el costo y las expectativas evita abandonos."]}],"errores":[{"error":"Pensar que los nuevos fármacos son solo para bajar la glucosa.","correccion":"Los iSGLT2 y GLP-1 tienen beneficios cardiorrenales y de peso que guían la elección."},{"error":"Iniciar un GLP-1 a dosis alta.","correccion":"La titulación gradual reduce los efectos gastrointestinales."},{"error":"No educar sobre cetoacidosis euglucémica con iSGLT2.","correccion":"La educación sobre días de enfermedad y síntomas es esencial."}],"comprueba":[{"pregunta":"¿Cuál es el beneficio principal de los iSGLT2?","respuesta":"Reducir hospitalizaciones por insuficiencia cardíaca y la progresión renal."},{"pregunta":"¿Qué efecto tiene un agonista GLP-1 sobre el apetito?","respuesta":"Lo reduce, lo que ayuda a la pérdida de peso."},{"pregunta":"¿Qué diferencia a tirzepatida?","respuesta":"Es un agonista dual GIP/GLP-1 con mayor efecto sobre el peso y la HbA1c en muchos pacientes."}],"resumen":["iSGLT2, GLP-1 y tirzepatida actúan en **lugares distintos**.","Sus beneficios van **más allá de la glucosa**.","La elección depende de corazón, riñón, peso y seguridad.","La **titulación y la educación** son parte del tratamiento."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Jardiance 10 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/114930014/FT_114930014.html"},{"cita":"AEMPS-CIMA. Ficha técnica de Mounjaro 10 mg/dosis KwikPen solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/1221685055/FT_1221685055.html"}],"imagenes":[{"ubicacion":"Sección de grupos","descripcion":"Tres columnas con corazón, riñón y balanza, y los fármacos que actúan en cada una.","alt":"iSGLT2, GLP-1 y tirzepatida más allá de la glucosa"}],"keywords":["isglt2 glp-1 tirzepatida","antidiabéticos beneficio cardiovascular","isglt2 insuficiencia cardiaca","glp-1 peso","tirzepatida mecanismo","diabetes más allá de la glucosa","curso farmacoterapia diabetes"],"mapa":{"centro":"Más allá de la glucosa","ramas":[{"titulo":"iSGLT2","icono":"Droplets","nodos":["Glucosuria","Insuficiencia cardíaca","Riñón"]},{"titulo":"GLP-1","icono":"Activity","nodos":["Incretina","Peso","Aterosclerosis"]},{"titulo":"Tirzepatida","icono":"Scale","nodos":["GIP + GLP-1","Peso","HbA1c"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Cetoacidosis","Infecciones","Gastrointestinal","Tiroides"]}]},"proceso":{"titulo":"Cómo elegir entre los nuevos grupos","intro":"","pasos":[{"titulo":"Evaluar el riesgo","detalle":"Enfermedad cardiovascular, insuficiencia cardíaca, ERC y obesidad.","icono":"ShieldCheck","evidencia":"Evaluación de riesgo."},{"titulo":"Definir el objetivo","detalle":"Reducir eventos, peso, HbA1c o síntomas.","icono":"Target","evidencia":"Meta acordada."},{"titulo":"Elegir el grupo","detalle":"iSGLT2, GLP-1 o tirzepatida según el perfil.","icono":"Pill","evidencia":"Selección justificada."},{"titulo":"Revisar seguridad","detalle":"Función renal, infecciones, gastrointestinal y tiroides.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Educar y seguir","detalle":"Titulación, técnica, efectos adversos y adherencia.","icono":"Users","evidencia":"Seguimiento."}]},"caso":{"titulo":"Insuficiencia cardíaca y obesidad","contexto":"Mujer de 62 años, diabetes tipo 2, insuficiencia cardíaca con fracción de eyección reducida, IMC 35 y HbA1c 8,1 %. Toma metformina y furosemida.","pregunta":"¿Qué grupo tiene prioridad?","opciones":[{"texto":"Solo aumentar la metformina.","correcta":false,"retro":"La metformina no es el fármaco con mayor beneficio en insuficiencia cardíaca y no aborda el riesgo de hospitalización."},{"texto":"Un iSGLT2 por el beneficio en insuficiencia cardíaca, y valorar un agonista GLP-1 o tirzepatida para el peso y la glucosa.","correcta":true,"retro":"El iSGLT2 reduce hospitalizaciones por insuficiencia cardíaca. El GLP-1 o tirzepatida pueden ayudar con el peso y la HbA1c, según el perfil."},{"texto":"Una sulfonilurea porque es más barata.","correcta":false,"retro":"La sulfonilurea no tiene beneficio en insuficiencia cardíaca y puede causar hipoglucemia."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: iSGLT2, agonistas GLP-1 y tirzepatida, más allá de la glucosa$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: iSGLT2, agonistas GLP-1 y tirzepatida, más allá de la glucosa$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 04. iSGLT2: mecanismo, indicaciones y beneficios en insuficiencia cardiaca y enfermedad renal
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La glucosa que se va por la orina","texto":"Un paciente pregunta por qué un medicamento para la diabetes “hace orinar azúcar” y por qué eso puede proteger el corazón y el riñón. La respuesta está en el túbulo proximal: los iSGLT2 bloquean la reabsorción de glucosa y sodio, aumentan la glucosuria y reducen la congestión. Ese mecanismo explica tanto los beneficios como los efectos adversos."},"objetivos":["Explicar el mecanismo renal de los iSGLT2.","Reconocer las indicaciones en diabetes, insuficiencia cardíaca y enfermedad renal.","Interpretar los beneficios cardiorrenales de los ensayos clínicos.","Ajustar la elección según la TFG y la comorbilidad."],"conceptos":[{"icono":"Droplets","termino":"SGLT2","definicion":"Cotransportador sodio-glucosa tipo 2 en el túbulo proximal; reabsorbe la mayor parte de la glucosa filtrada."},{"icono":"Activity","termino":"Glucosuria","definicion":"Pérdida de glucosa por la orina; reduce la glucosa y aporta un efecto diurético osmótico."},{"icono":"ShieldCheck","termino":"Cardiorrenal","definicion":"Beneficio sobre eventos cardiovasculares, insuficiencia cardíaca y progresión de la enfermedad renal."},{"icono":"Droplets","termino":"TFG","definicion":"La función renal guía el inicio y la continuación; los iSGLT2 pueden iniciarse con TFG baja en indicaciones específicas."}],"secciones":[{"titulo":"Cómo funcionan","parrafos":["En el túbulo proximal, el SGLT2 reabsorbe glucosa junto con sodio. Los iSGLT2 bloquean ese transportador, aumentan la glucosa en la orina y reducen la reabsorción de sodio. El efecto diurético osmótico disminuye la congestión y la presión intraglomerular, lo que ayuda a explicar el beneficio en insuficiencia cardíaca y enfermedad renal.","El efecto sobre la HbA1c es modesto, de aproximadamente 0,5 a 1 punto, y disminuye con la TFG. Sin embargo, el beneficio cardiorrenal se observa incluso con TFG baja y no depende solo de la glucosa. Por eso se usan en pacientes con insuficiencia cardíaca o ERC, tengan o no diabetes."]},{"titulo":"Indicaciones y evidencia","parrafos":["Los iSGLT2 reducen hospitalizaciones por insuficiencia cardíaca y muerte cardiovascular en pacientes con insuficiencia cardíaca, independientemente de la diabetes. En enfermedad renal crónica con albuminuria, reducen la progresión y los eventos renales. En diabetes tipo 2 con alto riesgo cardiovascular, también reducen eventos.","La elección entre empagliflozina, dapagliflozina y otros depende de la indicación, la TFG, el costo y la cobertura. La evidencia no es idéntica para todos los fármacos y poblaciones, pero la clase comparte beneficios. La decisión debe basarse en el perfil y en la ficha técnica."]},{"titulo":"TFG y educación","parrafos":["Los iSGLT2 pueden iniciarse con TFG ≥20 ml/min en muchas indicaciones, según el fármaco y la ficha técnica. La TFG puede disminuir de forma transitoria al inicio por el efecto hemodinámico; no es motivo de suspensión si es leve y estable. Se revisa la función renal después de iniciar.","La educación incluye hidratación, higiene genital, signos de infección, cetoacidosis euglucémica y reglas de días de enfermedad. El paciente debe saber que el efecto diurético puede aumentar la micción y que no debe suspenderlo por una infección leve sin consultar."]}],"errores":[{"error":"Suspender el iSGLT2 por una caída transitoria de la TFG.","correccion":"La caída inicial puede ser hemodinámica y no siempre requiere suspensión; se evalúa."},{"error":"No revisar el volumen ni los diuréticos.","correccion":"El efecto diurético puede causar hipotensión o deshidratación."},{"error":"Olvidar la cetoacidosis euglucémica.","correccion":"Se educa sobre síntomas y reglas de días de enfermedad, aunque la glucosa no esté alta."}],"comprueba":[{"pregunta":"¿Dónde actúan los iSGLT2?","respuesta":"En el cotransportador sodio-glucosa tipo 2 del túbulo proximal renal."},{"pregunta":"¿Cuál es su beneficio en insuficiencia cardíaca?","respuesta":"Reducen hospitalizaciones y muerte cardiovascular."},{"pregunta":"¿Qué efecto adverso grave se debe vigilar?","respuesta":"La cetoacidosis euglucémica."}],"resumen":["Los iSGLT2 bloquean la **reabsorción renal de glucosa y sodio**.","Reducen eventos de **insuficiencia cardíaca y progresión renal**.","El beneficio no depende solo de la HbA1c.","La educación sobre volumen, infecciones y cetoacidosis es clave."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Jardiance 10 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/114930014/FT_114930014.html"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Sección de mecanismo","descripcion":"Nefrona simplificada con el túbulo proximal, el SGLT2 bloqueado y la glucosa saliendo en la orina.","alt":"Mecanismo renal de los iSGLT2"}],"keywords":["isglt2 mecanismo","dapagliflozina insuficiencia cardiaca","empagliflozina enfermedad renal","isglt2 tfg","glucosuria diabetes","beneficio cardiorrenal isglt2","curso farmacoterapia diabetes"],"mapa":{"centro":"iSGLT2","ramas":[{"titulo":"Riñón","icono":"Droplets","nodos":["Bloqueo SGLT2","Glucosuria","Menos congestión"]},{"titulo":"Corazón","icono":"Activity","nodos":["Menos hospitalizaciones","Mejor carga de volumen","Beneficio en IC"]},{"titulo":"Glucosa","icono":"Target","nodos":["HbA1c modesta","Sin hipoglucemia sola","Peso ligeramente menor"]},{"titulo":"Indicaciones","icono":"ClipboardList","nodos":["DM2","Insuficiencia cardíaca","ERC con albuminuria"]}]},"proceso":{"titulo":"Cómo iniciar un iSGLT2","intro":"","pasos":[{"titulo":"Confirmar indicación","detalle":"Diabetes, insuficiencia cardíaca o ERC con albuminuria.","icono":"Target","evidencia":"Indicación documentada."},{"titulo":"Revisar TFG","detalle":"Verificar el umbral del fármaco y la función renal.","icono":"Calculator","evidencia":"TFG."},{"titulo":"Revisar volumen","detalle":"Diuréticos, hipotensión y riesgo de depleción.","icono":"Droplets","evidencia":"Evaluación de volumen."},{"titulo":"Educar","detalle":"Micción, infecciones, cetoacidosis y días de enfermedad.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"TFG, presión, síntomas y adherencia.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Insuficiencia cardíaca y TFG 32","contexto":"Hombre de 70 años, diabetes tipo 2, insuficiencia cardíaca con fracción de eyección reducida, TFG 32 ml/min y albuminuria. Toma furosemida y metformina.","pregunta":"¿Cuál es la conducta más razonable?","opciones":[{"texto":"No usar iSGLT2 porque la TFG es baja.","correcta":false,"retro":"Los iSGLT2 tienen beneficio en insuficiencia cardíaca y pueden usarse con TFG baja, según el fármaco y la ficha técnica."},{"texto":"Proponer un iSGLT2 con beneficio en insuficiencia cardíaca, revisar volumen y función renal, y ajustar el resto del esquema.","correcta":true,"retro":"El beneficio cardiorrenal es independiente de la glucosa. Se revisa la diuresis, la presión y la TFG."},{"texto":"Sustituir la furosemida por el iSGLT2.","correcta":false,"retro":"El iSGLT2 no reemplaza al diurético; se añade y se ajusta el volumen según la respuesta."}]}}$j$::jsonb;
