  END IF;

  -- 05. Seguridad de los iSGLT2: cetoacidosis euglucémica, depleción de volumen, infecciones y reglas de días de enfermedad
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La cetoacidosis con glucosa de 180","texto":"Una paciente con diabetes tipo 2 y un iSGLT2 llega a urgencias con náuseas, dolor abdominal y respiración rápida. La glucosa es 180 mg/dL, no 500. El médico piensa en un cuadro viral, pero las cetonas están altas y el pH bajo. Es una cetoacidosis euglucémica, una complicación rara pero grave de los iSGLT2 que no se detecta mirando solo la glucosa."},"objetivos":["Reconocer la cetoacidosis euglucémica y sus desencadenantes.","Prevenir la depleción de volumen y las infecciones genitales.","Aplicar las reglas de días de enfermedad en pacientes con iSGLT2.","Educar al paciente y al cuidador sobre signos de alarma."],"conceptos":[{"icono":"AlertTriangle","termino":"Cetoacidosis euglucémica","definicion":"Acidosis con cetonas elevadas y glucosa no muy alta; puede ocurrir con iSGLT2 en cirugía, infección, ayuno o alcohol."},{"icono":"Droplets","termino":"Depleción de volumen","definicion":"Pérdida de líquidos por diuresis osmótica; aumenta con diuréticos, calor o baja ingesta."},{"icono":"Bug","termino":"Infección genital","definicion":"Candidiasis vulvovaginal o balanitis por glucosuria; se previene con higiene y se trata oportunamente."},{"icono":"ShieldCheck","termino":"Días de enfermedad","definicion":"Suspender el iSGLT2 durante enfermedad aguda, cirugía, ayuno prolongado o deshidratación, y reiniciar al recuperarse."}],"secciones":[{"titulo":"Cetoacidosis euglucémica","parrafos":["Los iSGLT2 pueden favorecer la cetogénesis, sobre todo en situaciones de estrés: cirugía, infección, infarto, ayuno prolongado, alcohol o reducción brusca de insulina. La glucosa puede estar solo moderadamente elevada, por debajo de 250 mg/dL, pero las cetonas y la acidosis están presentes. Los síntomas incluyen náuseas, vómito, dolor abdominal, sed, respiración rápida y confusión.","Ante la sospecha, se suspende el iSGLT2, se hidrata y se busca atención urgente. No se debe descartar por una glucosa “normal”. La educación debe incluir esta posibilidad, especialmente antes de cirugías o procedimientos."]},{"titulo":"Volumen e infecciones","parrafos":["El efecto diurético puede causar hipotensión, mareo o deshidratación, sobre todo en personas mayores, con diuréticos o con baja ingesta. Se recomienda hidratación adecuada y revisión de la presión. En climas calurosos o durante el ejercicio intenso, el riesgo aumenta.","La glucosuria favorece las infecciones genitales por hongos. La higiene, la ropa adecuada y la consulta temprana ayudan. La balanitis en hombres y la vulvovaginitis en mujeres son las más frecuentes. No suelen requerir suspender el fármaco, pero deben tratarse."]},{"titulo":"Reglas de días de enfermedad","parrafos":["Cuando el paciente tiene vómito, diarrea, fiebre alta, no puede comer o beber, o va a someterse a cirugía, se suspende el iSGLT2 temporalmente. Se reinicia cuando esté estable y haya recuperado la ingesta. El equipo tratante debe conocer la suspensión.","El Químico Farmacéutico puede entregar una tarjeta o un mensaje claro con las reglas: qué suspender, cuándo consultar y cuándo reiniciar. También puede revisar la medicación durante la dispensación y preguntar por procedimientos programados."]}],"errores":[{"error":"Descartar cetoacidosis por glucosa <250.","correccion":"La cetoacidosis euglucémica existe; hay que medir cetonas y valorar el pH."},{"error":"No suspender el iSGLT2 antes de cirugía.","correccion":"Se suspende según el protocolo para reducir el riesgo de cetoacidosis."},{"error":"Ignorar la higiene genital.","correccion":"La glucosuria favorece infecciones; la educación y el tratamiento oportuno son importantes."}],"comprueba":[{"pregunta":"¿Qué es la cetoacidosis euglucémica?","respuesta":"Una acidosis con cetonas elevadas y glucosa no muy alta, asociada a iSGLT2 en situaciones de estrés."},{"pregunta":"¿Cuándo se suspende el iSGLT2?","respuesta":"En enfermedad aguda, cirugía, ayuno prolongado o deshidratación."},{"pregunta":"¿Qué infección es frecuente con iSGLT2?","respuesta":"La candidiasis genital y la balanitis."}],"resumen":["La cetoacidosis euglucémica es **rara pero grave**.","La glucosa normal no descarta el problema.","Las **reglas de días de enfermedad** son obligatorias.","La higiene y la hidratación reducen infecciones y deshidratación."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Jardiance 10 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/114930014/FT_114930014.html"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Sección de cetoacidosis","descripcion":"Tira reactiva de cetonas positiva junto a un glucómetro que marca 190 mg/dL y una caja de iSGLT2.","alt":"Cetoacidosis euglucémica por iSGLT2"}],"keywords":["cetoacidosis euglucémica isglt2","isglt2 efectos adversos","isglt2 días de enfermedad","infección genital isglt2","isglt2 cirugía","dapagliflozina seguridad","empagliflozina seguridad"],"mapa":{"centro":"Seguridad iSGLT2","ramas":[{"titulo":"Cetoacidosis","icono":"AlertTriangle","nodos":["Glucosa no muy alta","Cetonas","Cirugía o infección"]},{"titulo":"Volumen","icono":"Droplets","nodos":["Diuresis","Hipotensión","Diuréticos"]},{"titulo":"Infecciones","icono":"Bug","nodos":["Candidiasis","Balanitis","Higiene"]},{"titulo":"Suspensión","icono":"ShieldCheck","nodos":["Enfermedad aguda","Cirugía","Ayuno"]}]},"proceso":{"titulo":"Prevención de complicaciones con iSGLT2","intro":"","pasos":[{"titulo":"Educar al inicio","detalle":"Explicar cetoacidosis, volumen, infecciones y días de enfermedad.","icono":"Users","evidencia":"Educación documentada."},{"titulo":"Revisar volumen","detalle":"Presión, diuréticos, calor y capacidad de hidratación.","icono":"Droplets","evidencia":"Evaluación."},{"titulo":"Antes de cirugía","detalle":"Suspender según el protocolo y coordinar el reinicio.","icono":"CalendarClock","evidencia":"Indicación registrada."},{"titulo":"Enfermedad aguda","detalle":"Suspender si hay vómito, diarrea, fiebre o mala ingesta.","icono":"AlertTriangle","evidencia":"Regla aplicada."},{"titulo":"Reiniciar","detalle":"Cuando el paciente esté estable y tolerando líquidos.","icono":"CheckCircle2","evidencia":"Reinicio."}]},"caso":{"titulo":"Náuseas y glucosa 190","contexto":"Mujer de 58 años con diabetes tipo 2, iSGLT2, infección urinaria y vómito. Glucosa 190 mg/dL, cetonas positivas, pH 7,28.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Descartar cetoacidosis porque la glucosa no es alta.","correcta":false,"retro":"La cetoacidosis euglucémica puede ocurrir con glucosa moderada. Las cetonas y el pH son clave."},{"texto":"Suspender el iSGLT2, hidratar y remitir a urgencias para manejo de la cetoacidosis.","correcta":true,"retro":"Es una emergencia. Se suspende el fármaco, se trata la infección y se corrige la acidosis."},{"texto":"Aumentar la insulina y continuar el iSGLT2.","correcta":false,"retro":"El iSGLT2 debe suspenderse durante la enfermedad aguda."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Seguridad de los iSGLT2: cetoacidosis euglucémica, depleción de volumen, infecciones y reglas de días de enfermedad$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Seguridad de los iSGLT2: cetoacidosis euglucémica, depleción de volumen, infecciones y reglas de días de enfermedad$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
