    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 06. Liraglutida: mecanismo, esquemas de titulación y evidencia en diabetes tipo 2 y obesidad
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La pluma que se empieza despacio","texto":"Un paciente recibe liraglutida para diabetes y obesidad, se inyecta la dosis completa el primer día y a las pocas horas tiene náuseas intensas. La titulación gradual no es un capricho: reduce los efectos gastrointestinales y mejora la adherencia. La liraglutida puede ser muy útil, pero solo si se usa con el esquema correcto."},"objetivos":["Explicar el mecanismo de la liraglutida y su efecto sobre la glucosa y el peso.","Aplicar el esquema de titulación y la técnica de inyección.","Reconocer la evidencia en diabetes tipo 2 y obesidad.","Identificar los efectos adversos y las precauciones."],"conceptos":[{"icono":"Activity","termino":"GLP-1","definicion":"Incretina que estimula la insulina dependiente de glucosa, frena el glucagón y reduce el apetito."},{"icono":"Scale","termino":"Peso","definicion":"La liraglutida reduce el peso por menor ingesta y enlentecimiento del vaciamiento gástrico."},{"icono":"Syringe","termino":"Titulación","definicion":"Aumento gradual de la dosis para reducir náuseas, vómito y diarrea."},{"icono":"AlertTriangle","termino":"Gastrointestinal","definicion":"Náuseas, vómito, diarrea y estreñimiento son los efectos más frecuentes; suelen disminuir con el tiempo."}],"secciones":[{"titulo":"Cómo actúa y qué logra","parrafos":["La liraglutida es un agonista del receptor GLP-1 que se administra una vez al día. Estimula la secreción de insulina cuando hay glucosa, reduce el glucagón, enlentece el vaciamiento gástrico y disminuye el apetito. El resultado es una reducción de la HbA1c y del peso, con bajo riesgo de hipoglucemia cuando se usa sola.","En diabetes tipo 2, la liraglutida reduce la HbA1c y el peso. En obesidad, la dosis de 3 mg al día ha demostrado pérdida de peso clínicamente significativa. La evidencia cardiovascular es favorable en pacientes con alto riesgo, aunque no es idéntica a la de otros agonistas GLP-1."]},{"titulo":"Titulación y técnica","parrafos":["Se inicia con 0,6 mg al día durante una semana y se aumenta a 1,2 mg; si es necesario, se puede subir a 1,8 mg y luego a 2,4 o 3 mg. La titulación semanal reduce los síntomas digestivos. Si aparecen náuseas intensas, se puede mantener la dosis actual o reducir temporalmente.","La inyección se aplica por vía subcutánea en abdomen, muslo o brazo, rotando el sitio. La pluma se conserva refrigerada antes del primer uso y luego a temperatura ambiente según la ficha técnica. Se debe revisar la técnica, el horario y la adherencia."]},{"titulo":"Seguridad y poblaciones especiales","parrafos":["Los efectos adversos más frecuentes son gastrointestinales. Se han descrito pancreatitis, colelitiasis y reacciones en el sitio de inyección. No se recomienda en antecedente personal o familiar de carcinoma medular de tiroides ni en síndrome de neoplasia endocrina múltiple tipo 2. En insuficiencia renal grave se usa con precaución.","No se recomienda en el embarazo ni en la lactancia. En adultos mayores, la pérdida de peso y la deshidratación pueden aumentar el riesgo de caídas. La educación sobre náuseas, hidratación y signos de pancreatitis es parte del tratamiento."]}],"errores":[{"error":"Iniciar con la dosis objetivo.","correccion":"Se empieza bajo y se titula semanalmente."},{"error":"No preguntar por antecedente de pancreatitis o tiroides.","correccion":"Son contraindicaciones o precauciones importantes."},{"error":"No revisar la técnica de inyección.","correccion":"La técnica y la conservación afectan la eficacia y la seguridad."}],"comprueba":[{"pregunta":"¿Cómo se titula la liraglutida?","respuesta":"Se inicia con 0,6 mg al día y se aumenta gradualmente según tolerancia."},{"pregunta":"¿Cuál es el efecto adverso más frecuente?","respuesta":"Náuseas y otros síntomas gastrointestinales."},{"pregunta":"¿En quién se evita?","respuesta":"En antecedente de carcinoma medular de tiroides, MEN2, embarazo o pancreatitis recurrente."}],"resumen":["La liraglutida actúa sobre **GLP-1** y reduce glucosa y peso.","La **titulación** es clave para la tolerancia.","Se vigilan pancreatitis, colelitiasis y tiroides.","La técnica de inyección y la adherencia sostienen el resultado."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Saxenda 6 mg/ml solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/115992002/FT_115992002.html"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Sección de titulación","descripcion":"Pluma de liraglutida con una flecha que sube en escalones semanales de 0,6 a 3 mg.","alt":"Titulación de liraglutida"}],"keywords":["liraglutida dosis","liraglutida titulación","liraglutida diabetes tipo 2","liraglutida obesidad","liraglutida efectos secundarios","glp-1 liraglutida","curso farmacoterapia diabetes"],"mapa":{"centro":"Liraglutida","ramas":[{"titulo":"Mecanismo","icono":"Activity","nodos":["Incretina","Insulina dependiente de glucosa","Menos apetito"]},{"titulo":"Titulación","icono":"Syringe","nodos":["Inicio bajo","Aumento semanal","Dosis objetivo"]},{"titulo":"Evidencia","icono":"LineChart","nodos":["HbA1c","Peso","Riesgo cardiovascular"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Náuseas","Pancreatitis","Colelitiasis","Tiroides"]}]},"proceso":{"titulo":"Cómo iniciar liraglutida","intro":"","pasos":[{"titulo":"Confirmar indicación","detalle":"Diabetes tipo 2, obesidad o ambas, según la ficha técnica.","icono":"Target","evidencia":"Indicación."},{"titulo":"Revisar contraindicaciones","detalle":"Tiroides, pancreatitis, embarazo y función renal.","icono":"ShieldCheck","evidencia":"Evaluación."},{"titulo":"Iniciar bajo","detalle":"0,6 mg al día durante una semana.","icono":"Syringe","evidencia":"Dosis inicial."},{"titulo":"Titular","detalle":"Aumentar según tolerancia y objetivo.","icono":"RefreshCw","evidencia":"Esquema."},{"titulo":"Seguir","detalle":"Peso, HbA1c, tolerancia y técnica.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Náuseas en la primera semana","contexto":"Mujer de 45 años con diabetes tipo 2 y obesidad. Inició liraglutida 1,8 mg al día desde el primer día y consulta con náuseas intensas y vómito.","pregunta":"¿Qué recomendar?","opciones":[{"texto":"Suspender definitivamente.","correcta":false,"retro":"La mayoría de los síntomas mejoran con titulación. Suspender sin intentar el esquema adecuado priva de un tratamiento útil."},{"texto":"Reducir a 0,6 mg, hidratar y volver a titular gradualmente.","correcta":true,"retro":"La titulación lenta reduce los síntomas. Si hay deshidratación o dolor abdominal intenso, se evalúa pancreatitis."},{"texto":"Aumentar la dosis para que el cuerpo se acostumbre.","correcta":false,"retro":"Aumentar la dosis empeora los síntomas gastrointestinales."}]}}$j$::jsonb;
