  -- 07. Semaglutida subcutánea y oral: dosificación, evidencia cardiorrenal y seguridad
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La misma molécula, dos caminos","texto":"Una paciente pregunta si la semaglutida oral “es más suave” que la inyectable. La respuesta depende de la dosis, la absorción y la adherencia. La semaglutida oral tiene reglas estrictas de administración; la subcutánea tiene una titulación semanal. Ambas pueden ser eficaces, pero no son intercambiables sin criterio."},"objetivos":["Diferenciar la semaglutida subcutánea y oral en dosis y administración.","Explicar la evidencia cardiorrenal y de peso.","Reconocer los efectos adversos y las precauciones.","Elegir la formulación según el paciente y la cobertura."],"conceptos":[{"icono":"Activity","termino":"Semaglutida","definicion":"Agonista GLP-1 de acción prolongada que reduce HbA1c y peso, con beneficios cardiovasculares en pacientes de riesgo."},{"icono":"Syringe","termino":"Subcutánea","definicion":"Aplicación semanal con titulación gradual; no depende de la comida."},{"icono":"Pill","termino":"Oral","definicion":"Tableta diaria que debe tomarse en ayunas con poca agua y esperar al menos 30 minutos antes de comer."},{"icono":"ShieldCheck","termino":"Cardiorrenal","definicion":"Reducción de eventos cardiovasculares y posible beneficio renal en pacientes seleccionados."}],"secciones":[{"titulo":"Dos formulaciones, reglas distintas","parrafos":["La semaglutida subcutánea se administra una vez a la semana, con titulación gradual desde 0,25 mg hasta 0,5 o 1 mg, según el objetivo. La formulación oral se toma una vez al día en ayunas, con un máximo de 120 ml de agua, y no se debe comer ni tomar otros medicamentos durante al menos 30 minutos. Esas reglas son esenciales para la absorción.","La semaglutida oral y la subcutánea no son intercambiables miligramo a miligramo. La elección depende de la preferencia, la adherencia, la cobertura y la capacidad de seguir las instrucciones. La inyectable puede ser más cómoda para quien olvida la toma diaria; la oral puede ser preferida por quien evita las agujas."]},{"titulo":"Evidencia y beneficios","parrafos":["La semaglutida reduce la HbA1c y el peso de forma significativa. En pacientes con diabetes tipo 2 y alto riesgo cardiovascular, la formulación subcutánea ha demostrado reducción de eventos cardiovasculares mayores. También se ha estudiado su beneficio en insuficiencia cardíaca y enfermedad renal, con resultados que dependen de la población y la formulación.","En obesidad, dosis más altas de semaglutida han mostrado pérdida de peso clínicamente relevante. La evidencia no convierte el fármaco en un tratamiento estético: se usa en personas con indicación clínica, acompañado de alimentación y actividad, y con seguimiento de efectos adversos."]},{"titulo":"Seguridad y educación","parrafos":["Los efectos gastrointestinales son los más frecuentes: náuseas, vómito, diarrea, estreñimiento y dolor abdominal. Suelen mejorar con la titulación. Se han descrito pancreatitis, colelitiasis y complicaciones de la retinopatía en pacientes con diabetes y retinopatía preexistente, por lo que se recomienda vigilancia.","No se usa en embarazo ni lactancia. Se evita en antecedente de carcinoma medular de tiroides o MEN2. La educación incluye técnica de inyección, conservación, reglas de la formulación oral, hidratación y signos de alarma. El QF puede revisar la adherencia y la cobertura."]}],"errores":[{"error":"Tomar semaglutida oral con alimentos.","correccion":"Se toma en ayunas, con poca agua, y se espera 30 minutos."},{"error":"Cambiar de formulación sin ajustar la dosis.","correccion":"Las formulaciones no son intercambiables mg a mg; se sigue el esquema de cada una."},{"error":"No preguntar por retinopatía.","correccion":"En pacientes con retinopatía preexistente se requiere vigilancia."}],"comprueba":[{"pregunta":"¿Cómo se toma la semaglutida oral?","respuesta":"En ayunas, con hasta 120 ml de agua, y sin comer ni tomar otros medicamentos durante 30 minutos."},{"pregunta":"¿Cuál es la frecuencia de la subcutánea?","respuesta":"Una vez a la semana, con titulación gradual."},{"pregunta":"¿Qué beneficio cardiovascular tiene?","respuesta":"Reduce eventos cardiovasculares mayores en pacientes de alto riesgo."}],"resumen":["La semaglutida tiene **dos formulaciones** con reglas distintas.","La oral exige **ayunas y 30 minutos** antes de comer.","La subcutánea es **semanal** y se titula.","La evidencia incluye HbA1c, peso y eventos cardiovasculares."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Wegovy 0,25 mg FlexTouch solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/1211608006/FT_1211608006.html"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"INVIMA. Alerta sanitaria 090-2024: semaglutida + vitamina B12.","url":"https://www.invima.gov.co/biblioteca/alerta-sanitaria-semglutida-vitamina-b12-090-2024"}],"imagenes":[{"ubicacion":"Sección de formulaciones","descripcion":"Dos caminos paralelos: una pluma semanal y una tableta con reloj de 30 minutos.","alt":"Semaglutida subcutánea y oral"}],"keywords":["semaglutida oral","semaglutida subcutánea","semaglutida dosis","semaglutida ayunas","semaglutida evidencia cardiovascular","semaglutida efectos secundarios","ozempic wegovy","curso farmacoterapia diabetes"],"mapa":{"centro":"Semaglutida","ramas":[{"titulo":"Subcutánea","icono":"Syringe","nodos":["Semanal","Titulación","No depende de comidas"]},{"titulo":"Oral","icono":"Pill","nodos":["Diaria","Ayunas","30 minutos"]},{"titulo":"Efectos","icono":"LineChart","nodos":["HbA1c","Peso","Corazón"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Gastrointestinal","Pancreatitis","Tiroides","Embarazo"]}]},"proceso":{"titulo":"Cómo elegir la formulación","intro":"","pasos":[{"titulo":"Evaluar preferencia","detalle":"Agujas, olvido de dosis, rutina y destreza.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Revisar cobertura","detalle":"Costo, disponibilidad y trámites.","icono":"Calculator","evidencia":"Acceso confirmado."},{"titulo":"Revisar seguridad","detalle":"Tiroides, pancreatitis, retinopatía y embarazo.","icono":"ShieldCheck","evidencia":"Evaluación."},{"titulo":"Iniciar y titular","detalle":"Dosis inicial y aumento gradual.","icono":"Syringe","evidencia":"Esquema."},{"titulo":"Seguir","detalle":"HbA1c, peso, tolerancia y adherencia.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"La tableta que no funciona","contexto":"Paciente con semaglutida oral que la toma con el desayuno y café. HbA1c no mejora y refiere náuseas leves.","pregunta":"¿Qué revisar primero?","opciones":[{"texto":"Aumentar la dosis.","correcta":false,"retro":"Antes de aumentar, hay que confirmar que la toma es correcta. Con comida o café la absorción disminuye."},{"texto":"Revisar la administración: ayunas, poca agua y 30 minutos antes de comer.","correcta":true,"retro":"La semaglutida oral tiene reglas estrictas. Si no se cumplen, la exposición puede ser insuficiente."},{"texto":"Cambiar a insulina de inmediato.","correcta":false,"retro":"La insulina no es el siguiente paso automático; primero se corrige la administración y se evalúa la respuesta."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Semaglutida subcutánea y oral: dosificación, evidencia cardiorrenal y seguridad$t$ AND deleted_at IS NULL
