     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 08. Tirzepatida: agonista dual GIP/GLP-1, titulación, seguridad y alertas
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El doble agonista que cambió la conversación","texto":"Un paciente con diabetes y obesidad pregunta por tirzepatida porque “dicen que baja más el peso”. Es un agonista dual GIP/GLP-1 con resultados importantes en HbA1c y peso, pero no es un producto de estética ni una fórmula mágica. Requiere indicación, titulación, seguimiento y vigilancia de efectos adversos."},"objetivos":["Explicar el mecanismo dual GIP/GLP-1 de la tirzepatida.","Aplicar el esquema de titulación y la técnica de inyección.","Reconocer la evidencia en diabetes y obesidad.","Identificar las alertas regulatorias y las precauciones."],"conceptos":[{"icono":"Activity","termino":"GIP","definicion":"Polipéptido insulinotrópico dependiente de glucosa; su activación junto con GLP-1 aumenta el efecto metabólico."},{"icono":"Scale","termino":"Peso","definicion":"La tirzepatida reduce el peso de forma significativa, además de mejorar la HbA1c."},{"icono":"Syringe","termino":"Titulación","definicion":"Aumento gradual cada cuatro semanas para reducir náuseas y vómito."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Se vigilan efectos gastrointestinales, pancreatitis, colelitiasis, tiroides y embarazo."}],"secciones":[{"titulo":"Qué es y cómo actúa","parrafos":["La tirzepatida es un agonista dual de los receptores GIP y GLP-1. Actúa sobre la secreción de insulina dependiente de glucosa, el glucagón, el vaciamiento gástrico y el apetito. En ensayos clínicos ha mostrado reducciones de HbA1c y peso superiores a las de algunos comparadores, con un perfil gastrointestinal característico.","No es un fármaco de primera línea para cualquier persona con sobrepeso. Se usa en diabetes tipo 2 y en obesidad, según la indicación aprobada, con evaluación clínica y seguimiento. La pérdida de peso debe acompañarse de alimentación adecuada y actividad física para preservar masa muscular."]},{"titulo":"Titulación y administración","parrafos":["Se inicia con 2,5 mg una vez a la semana durante cuatro semanas y se aumenta a 5 mg; luego puede subirse a 7,5, 10, 12,5 o 15 mg, con incrementos de al menos cuatro semanas. La titulación lenta reduce los efectos gastrointestinales. La inyección es subcutánea, en abdomen, muslo o brazo, rotando el sitio.","La pluma se conserva refrigerada antes del primer uso y luego según la ficha técnica. Se revisa la técnica y la adherencia. Si se olvida una dosis, se sigue la indicación de la ficha técnica; no se duplica."]},{"titulo":"Seguridad y alertas","parrafos":["Los efectos adversos más frecuentes son náuseas, diarrea, vómito, estreñimiento y dolor abdominal. Se han descrito pancreatitis, colelitiasis, reacciones en el sitio de inyección y hipoglucemia cuando se combina con insulina o sulfonilureas. No se recomienda en antecedente de carcinoma medular de tiroides o MEN2.","En Colombia, el INVIMA ha alertado sobre productos con tirzepatida sin registro sanitario. El QF debe verificar el registro, la cadena de suministro y la prescripción. La compra por internet o en lugares no autorizados es un riesgo para el paciente."]}],"errores":[{"error":"Iniciar con dosis altas para perder peso rápido.","correccion":"Se empieza con 2,5 mg y se titula cada cuatro semanas."},{"error":"No verificar el registro sanitario.","correccion":"El INVIMA ha alertado sobre productos falsificados; se verifica la cadena de suministro."},{"error":"No ajustar insulina o sulfonilurea.","correccion":"La combinación puede causar hipoglucemia; se ajustan las dosis."}],"comprueba":[{"pregunta":"¿Qué receptores activa la tirzepatida?","respuesta":"GIP y GLP-1."},{"pregunta":"¿Cómo se titula?","respuesta":"2,5 mg semanales durante cuatro semanas y aumentos graduales."},{"pregunta":"¿Qué alerta regulatoria existe en Colombia?","respuesta":"Productos con tirzepatida sin registro sanitario."}],"resumen":["La tirzepatida es un **agonista dual GIP/GLP-1**.","Reduce HbA1c y peso, con titulación lenta.","Se vigilan **gastrointestinales, pancreatitis y tiroides**.","Verificar el **registro sanitario** es obligatorio."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Mounjaro 10 mg/dosis KwikPen solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/1221685055/FT_1221685055.html"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Sección de titulación","descripcion":"Escalera de dosis de tirzepatida desde 2,5 hasta 15 mg con intervalos de cuatro semanas.","alt":"Titulación de tirzepatida"}],"keywords":["tirzepatida dosis","tirzepatida titulación","tirzepatida diabetes","tirzepatida obesidad","tirzepatida efectos secundarios","tirzepatida invima","agonista dual gip glp-1"],"mapa":{"centro":"Tirzepatida","ramas":[{"titulo":"Mecanismo","icono":"Activity","nodos":["GIP","GLP-1","Insulina y apetito"]},{"titulo":"Titulación","icono":"Syringe","nodos":["2,5 mg","Aumento cada 4 semanas","Dosis objetivo"]},{"titulo":"Efectos","icono":"Scale","nodos":["HbA1c","Peso","Saciedad"]},{"titulo":"Alertas","icono":"AlertTriangle","nodos":["Gastrointestinal","Pancreatitis","Tiroides","Productos falsos"]}]},"proceso":{"titulo":"Cómo iniciar tirzepatida","intro":"","pasos":[{"titulo":"Confirmar indicación","detalle":"Diabetes tipo 2 u obesidad, según la ficha técnica.","icono":"Target","evidencia":"Indicación."},{"titulo":"Revisar seguridad","detalle":"Tiroides, pancreatitis, embarazo, función renal y medicamentos.","icono":"ShieldCheck","evidencia":"Evaluación."},{"titulo":"Iniciar 2,5 mg","detalle":"Una vez a la semana durante cuatro semanas.","icono":"Syringe","evidencia":"Dosis inicial."},{"titulo":"Titular","detalle":"Aumentar cada cuatro semanas según tolerancia.","icono":"RefreshCw","evidencia":"Esquema."},{"titulo":"Seguir","detalle":"Peso, HbA1c, tolerancia y registro del producto.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"La pluma comprada por internet","contexto":"Paciente con obesidad y diabetes trae una pluma de tirzepatida comprada por internet, sin factura ni registro visible. Quiere empezar con 15 mg porque “así baja más rápido”.","pregunta":"¿Qué debe hacer el QF?","opciones":[{"texto":"Aplicarla porque el paciente ya la compró.","correcta":false,"retro":"Un producto sin registro ni cadena de frío verificable es un riesgo. No se debe administrar."},{"texto":"No administrarla, verificar el registro, explicar la titulación y derivar a una fuente autorizada.","correcta":true,"retro":"La seguridad del producto y la dosis correcta son prioritarias. Se empieza con 2,5 mg y se titula."},{"texto":"Dividir la dosis de 15 mg para que dure más.","correcta":false,"retro":"Las plumas no están diseñadas para fraccionar dosis y el producto no es verificable."}]}}$j$::jsonb;
