  -- 09. Cómo elegir entre iSGLT2, agonista GLP-1 y tirzepatida según el perfil del paciente
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Tres opciones, un paciente","texto":"Un hombre de 58 años con diabetes, obesidad, enfermedad coronaria y albuminuria pregunta cuál de los tres fármacos nuevos debe usar. La respuesta no es “el más nuevo” ni “el más caro”: es el que cubre el riesgo dominante, se tolera y se puede sostener. La elección combina evidencia, seguridad, acceso y preferencia."},"objetivos":["Comparar iSGLT2, GLP-1 y tirzepatida por beneficio y seguridad.","Seleccionar según enfermedad cardiovascular, insuficiencia cardíaca, ERC y obesidad.","Reconocer cuándo combinar y cuándo secuenciar.","Incorporar costo, adherencia y preferencias en la decisión."],"conceptos":[{"icono":"Activity","termino":"Riesgo dominante","definicion":"Problema que más amenaza al paciente: evento cardiovascular, insuficiencia cardíaca, progresión renal u obesidad."},{"icono":"Layers","termino":"Combinación","definicion":"Uso de fármacos con mecanismos complementarios para cubrir varios riesgos."},{"icono":"Calculator","termino":"Costo-efectividad","definicion":"Relación entre el beneficio clínico y el costo; importa para la sostenibilidad del tratamiento."},{"icono":"Users","termino":"Preferencia","definicion":"Lo que el paciente está dispuesto y puede hacer: vía, frecuencia, agujas, horario y costo."}],"secciones":[{"titulo":"Empezar por el riesgo dominante","parrafos":["Si el paciente tiene insuficiencia cardíaca, el iSGLT2 es prioritario. Si tiene enfermedad cardiovascular aterosclerótica, un agonista GLP-1 con evidencia reduce eventos. Si tiene enfermedad renal con albuminuria, el iSGLT2 es la base y algunos GLP-1 añaden beneficio. Si la obesidad es el problema dominante, tirzepatida o semaglutida pueden ser más eficaces para el peso.","La decisión no se basa en una sola variable. Un paciente puede tener insuficiencia cardíaca, obesidad y albuminuria; en ese caso, la combinación de iSGLT2 y GLP-1 puede ser razonable. La secuencia depende de la urgencia, la tolerancia y el acceso."]},{"titulo":"Combinar y secuenciar","parrafos":["Los iSGLT2 y los GLP-1 tienen mecanismos complementarios. La combinación puede mejorar la glucosa, el peso y los resultados cardiorrenales. Sin embargo, suma efectos adversos, costo y complejidad. Se recomienda iniciar uno, evaluar tolerancia y luego añadir el otro si está indicado.","La tirzepatida no se combina con otro agonista GLP-1. Si el paciente ya usa semaglutida o liraglutida, el cambio a tirzepatida debe ser una decisión médica, con titulación y seguimiento. La evidencia de combinación con iSGLT2 es favorable, pero requiere vigilancia de volumen y función renal."]},{"titulo":"El peso de la realidad","parrafos":["El costo y la cobertura pueden limitar la elección. Un fármaco no disponible no es una opción, aunque tenga buena evidencia. El QF puede revisar alternativas cubiertas, trámites y programas de acceso. También puede ayudar a priorizar el fármaco con mayor beneficio para el riesgo dominante.","La preferencia del paciente importa: algunos prefieren una pastilla, otros una inyección semanal, otros evitar las agujas. La educación sobre expectativas, efectos adversos y duración del tratamiento mejora la adherencia. La meta es un plan realista y sostenible."]}],"errores":[{"error":"Elegir solo por la HbA1c.","correccion":"El riesgo cardiovascular, renal y el peso también guían la elección."},{"error":"Combinar GLP-1 y tirzepatida.","correccion":"No se combinan; se elige uno."},{"error":"Ignorar el costo y la cobertura.","correccion":"Un plan inasequible no se sostiene; hay que buscar alternativas."}],"comprueba":[{"pregunta":"¿Qué fármaco se prioriza en insuficiencia cardíaca?","respuesta":"Un iSGLT2."},{"pregunta":"¿Qué fármaco se prioriza en obesidad y riesgo cardiovascular?","respuesta":"Un agonista GLP-1 con evidencia, o tirzepatida según el perfil."},{"pregunta":"¿Se pueden combinar GLP-1 y tirzepatida?","respuesta":"No; se elige uno de los dos."}],"resumen":["La elección empieza por el **riesgo dominante**.","iSGLT2 y GLP-1 pueden **combinarse** con seguimiento.","La tirzepatida no se combina con otro GLP-1.","El costo y la preferencia son parte de la decisión."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Jardiance 10 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/114930014/FT_114930014.html"},{"cita":"AEMPS-CIMA. Ficha técnica de Mounjaro 10 mg/dosis KwikPen solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/1221685055/FT_1221685055.html"}],"imagenes":[{"ubicacion":"Sección de decisión","descripcion":"Matriz de cuatro cuadrantes: corazón, riñón, peso y acceso, con los fármacos recomendados.","alt":"Cómo elegir entre iSGLT2, GLP-1 y tirzepatida"}],"keywords":["elegir isglt2 o glp-1","tirzepatida vs semaglutida","isglt2 glp-1 combinación","diabetes obesidad enfermedad cardiovascular","albuminuria isglt2","tratamiento diabetes personalizado","curso farmacoterapia diabetes"],"mapa":{"centro":"Elección del fármaco","ramas":[{"titulo":"Corazón","icono":"Activity","nodos":["iSGLT2 en IC","GLP-1 en aterosclerosis","Riesgo cardiovascular"]},{"titulo":"Riñón","icono":"Droplets","nodos":["iSGLT2","GLP-1 con evidencia","Albuminuria"]},{"titulo":"Peso","icono":"Scale","nodos":["Tirzepatida","Semaglutida","Liraglutida"]},{"titulo":"Persona","icono":"Users","nodos":["Costo","Adherencia","Preferencia","Tolerancia"]}]},"proceso":{"titulo":"Cómo decidir entre las opciones","intro":"","pasos":[{"titulo":"Definir el riesgo","detalle":"Cardiovascular, insuficiencia cardíaca, renal y obesidad.","icono":"ShieldCheck","evidencia":"Evaluación."},{"titulo":"Elegir el primero","detalle":"Fármaco con mayor beneficio para el riesgo dominante.","icono":"Target","evidencia":"Selección."},{"titulo":"Revisar acceso","detalle":"Costo, cobertura, disponibilidad y trámites.","icono":"Calculator","evidencia":"Acceso confirmado."},{"titulo":"Evaluar tolerancia","detalle":"Efectos adversos, adherencia y técnica.","icono":"Users","evidencia":"Seguimiento."},{"titulo":"Combinar si hace falta","detalle":"Añadir el segundo fármaco con seguimiento.","icono":"Layers","evidencia":"Plan ajustado."}]},"caso":{"titulo":"Coronaria, obesidad y albuminuria","contexto":"Hombre de 58 años, diabetes tipo 2, enfermedad coronaria, IMC 34, albuminuria y HbA1c 8,3 %. Toma metformina y estatina.","pregunta":"¿Qué estrategia es más integral?","opciones":[{"texto":"Solo aumentar metformina.","correcta":false,"retro":"No aborda el riesgo cardiovascular, renal ni el peso."},{"texto":"Iniciar un GLP-1 con beneficio cardiovascular y considerar un iSGLT2 por la albuminuria; revisar acceso y tolerancia.","correcta":true,"retro":"El GLP-1 cubre el riesgo aterosclerótico y el peso; el iSGLT2 cubre el riñón. La combinación puede ser razonable."},{"texto":"Tirzepatida sola aunque no haya evidencia cardiovascular específica.","correcta":false,"retro":"La tirzepatida es útil para peso y glucosa, pero en enfermedad coronaria se prefiere un fármaco con evidencia cardiovascular."}]}}$j$::jsonb;
