  -- 10. Caso: inicio de iSGLT2 y agonista GLP-1 en una persona con insuficiencia cardiaca, ERC e insulina
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Cuatro enfermedades y una sola consulta","texto":"Doña Lucía tiene 64 años, diabetes tipo 2, insuficiencia cardíaca, ERC con albuminuria y usa insulina basal. Su HbA1c es 8,4 %, tiene edema leve y ha ganado peso. El caso exige combinar beneficios cardiorrenales, ajustar insulina, revisar volumen y educar. No se resuelve con una sola receta."},"objetivos":["Integrar iSGLT2, GLP-1 e insulina en un paciente con múltiples comorbilidades.","Ajustar la insulina y los diuréticos al iniciar nuevos fármacos.","Prevenir hipoglucemias, deshidratación y cetoacidosis.","Diseñar un plan de seguimiento y educación realista."],"conceptos":[{"icono":"Activity","termino":"Insuficiencia cardíaca","definicion":"Síndrome con congestión o bajo gasto; los iSGLT2 reducen hospitalizaciones y muerte cardiovascular."},{"icono":"Droplets","termino":"ERC","definicion":"TFG baja o albuminuria; requiere ajuste de fármacos y nefroprotección."},{"icono":"Syringe","termino":"Insulina basal","definicion":"Insulina de acción prolongada que controla la glucosa entre comidas y en ayunas; requiere titulación y educación."},{"icono":"Layers","termino":"Combinación","definicion":"Uso de fármacos con mecanismos complementarios, con revisión de volumen, glucosa y tolerancia."}],"secciones":[{"titulo":"El plan inicial","parrafos":["En una paciente con insuficiencia cardíaca, ERC y albuminuria, el iSGLT2 tiene una indicación clara. El GLP-1 puede añadir beneficio cardiovascular y ayudar con el peso y la glucosa. La insulina basal se ajusta según las glucometrías y el riesgo de hipoglucemia. La combinación debe iniciarse de forma escalonada para distinguir efectos y tolerancia.","Antes de iniciar, se revisan la TFG, la presión, los diuréticos, el peso y las glucometrías. Se educa sobre cetoacidosis, infecciones, náuseas y hipoglucemia. Se acuerda un plan de seguimiento en dos a cuatro semanas."]},{"titulo":"Ajustes que evitan eventos","parrafos":["El iSGLT2 puede aumentar la diuresis; si la paciente toma furosemida, se revisa la dosis y se vigilan signos de deshidratación. El GLP-1 puede reducir el apetito y la ingesta; si se combina con insulina o sulfonilurea, se reduce el riesgo de hipoglucemia ajustando dosis. La insulina se titula con glucometrías, no con una cifra aislada.","La educación incluye qué hacer si hay vómito, diarrea o fiebre; cuándo suspender el iSGLT2; cómo tratar una hipoglucemia; y cuándo consultar. El cuidador debe conocer el plan. La adherencia se revisa en cada contacto."]},{"titulo":"Seguimiento y metas","parrafos":["La meta de HbA1c se individualiza. En una paciente con comorbilidad y riesgo de hipoglucemia, una meta menos estricta puede ser más segura. Se revisan peso, presión, TFG, albuminuria, eventos de hipoglucemia y efectos adversos. La revisión de la medicación completa evita duplicidades e interacciones.","El QF documenta la intervención y la comunica al equipo. Si el acceso a un fármaco es difícil, se busca una alternativa cubierta. La sostenibilidad del plan es parte del éxito clínico."]}],"errores":[{"error":"Iniciar todo al mismo tiempo sin seguimiento.","correccion":"La secuencia escalonada permite evaluar tolerancia y seguridad."},{"error":"No ajustar diuréticos o insulina.","correccion":"El iSGLT2 puede deshidratar y el GLP-1 puede reducir la ingesta; se ajustan las dosis."},{"error":"No educar sobre días de enfermedad.","correccion":"La suspensión temporal del iSGLT2 evita cetoacidosis."}],"comprueba":[{"pregunta":"¿Por qué iniciar iSGLT2 en insuficiencia cardíaca?","respuesta":"Porque reduce hospitalizaciones y muerte cardiovascular."},{"pregunta":"¿Qué ajustar al añadir GLP-1?","respuesta":"La insulina o sulfonilurea, para evitar hipoglucemia, y revisar la ingesta."},{"pregunta":"¿Qué vigilar con el iSGLT2?","respuesta":"Volumen, función renal, infecciones y cetoacidosis."}],"resumen":["La combinación se inicia de forma **escalonada**.","Se ajustan **insulina y diuréticos** según la respuesta.","La educación cubre hipoglucemia, cetoacidosis y días de enfermedad.","El seguimiento es **cardiorrenal y glucémico**."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Jardiance 10 mg comprimidos recubiertos con película.","url":"https://cima.aemps.es/cima/dochtml/ft/114930014/FT_114930014.html"},{"cita":"AEMPS-CIMA. Ficha técnica de Wegovy 0,25 mg FlexTouch solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/1211608006/FT_1211608006.html"}],"imagenes":[{"ubicacion":"Sección del caso","descripcion":"Paciente con edema leve, insulina, iSGLT2 y GLP-1, y un plan de seguimiento con corazón, riñón y glucosa.","alt":"Caso complejo de diabetes con insuficiencia cardíaca y ERC"}],"keywords":["caso clínico diabetes insuficiencia cardiaca","isglt2 glp-1 insulina","erc albuminuria diabetes","cetoacidosis isglt2","seguimiento farmacoterapéutico diabetes","combinación antidiabética","curso farmacoterapia diabetes"],"mapa":{"centro":"Caso complejo","ramas":[{"titulo":"Corazón","icono":"Activity","nodos":["iSGLT2","Diurético","Congestión"]},{"titulo":"Riñón","icono":"Droplets","nodos":["TFG","Albuminuria","Nefroprotección"]},{"titulo":"Glucosa","icono":"Target","nodos":["Insulina","GLP-1","Hipoglucemia"]},{"titulo":"Persona","icono":"Users","nodos":["Peso","Educación","Adherencia"]}]},"proceso":{"titulo":"Plan de inicio en el paciente complejo","intro":"","pasos":[{"titulo":"Revisar comorbilidades","detalle":"Insuficiencia cardíaca, ERC, albuminuria, peso y glucometrías.","icono":"ClipboardList","evidencia":"Evaluación."},{"titulo":"Iniciar iSGLT2","detalle":"Revisar TFG, volumen y diuréticos.","icono":"Droplets","evidencia":"Inicio."},{"titulo":"Añadir GLP-1","detalle":"Titular y ajustar insulina si hay riesgo de hipoglucemia.","icono":"Syringe","evidencia":"Esquema."},{"titulo":"Educar","detalle":"Cetoacidosis, hipoglucemia, volumen y días de enfermedad.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"TFG, peso, presión, HbA1c y eventos.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"Edema y glucemia 210","contexto":"Lucía, 64 años, insuficiencia cardíaca, ERC, albuminuria, insulina basal 30 UI, HbA1c 8,4 %, edema leve. Se inicia iSGLT2 y GLP-1.","pregunta":"¿Qué revisar en el seguimiento?","opciones":[{"texto":"Solo la HbA1c en tres meses.","correcta":false,"retro":"La HbA1c no detecta hipoglucemias, deshidratación ni progresión renal."},{"texto":"Peso, presión, TFG, glucometrías, hipoglucemias, tolerancia gastrointestinal y adherencia.","correcta":true,"retro":"El seguimiento debe cubrir corazón, riñón, glucosa y tolerancia."},{"texto":"Suspender la insulina de inmediato.","correcta":false,"retro":"La insulina se ajusta, no se suspende automáticamente; la paciente puede necesitarla."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Caso: inicio de iSGLT2 y agonista GLP-1 en una persona con insuficiencia cardiaca, ERC e insulina$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Caso: inicio de iSGLT2 y agonista GLP-1 en una persona con insuficiencia cardiaca, ERC e insulina$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (125_experiencias_farmacoterapia_diabetes_2.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Farmacoterapia de la Diabetes$t$, v_n;
END $exp$;
